'use strict';
const test=require('node:test');
const assert=require('node:assert/strict');
const {cargoAdditive,lockAdditive,libAdditive,versionBumpOnly,assess,CORE,LOCK,LIB,ROOT,NATIVE,WINDOWS}=require('./ci-shared-manifest-route.cjs');
const cargoDiff='@@ -12 +12 @@\n-node-catalog-lab = []\n+node-catalog-lab = ["dep:akula-node-catalog"]\n@@ -100,0 +100 @@\n+akula-node-catalog = { path = "../../modules/node-catalog", optional = true }\n';
const local=new Set(['akula-node-catalog']);
const before='# This file is automatically @generated by Cargo.\nversion = 4\n\n[[package]]\nname = "aquilum-core"\nversion = "0.3.10"\ndependencies = [\n "blake3",\n "serde",\n]\n\n[[package]]\nname = "serde"\nversion = "1.0.0"\nsource = "registry+https://github.com/rust-lang/crates.io-index"\nchecksum = "example"\n';
const after='# This file is automatically @generated by Cargo.\nversion = 4\n\n[[package]]\nname = "akula-node-catalog"\nversion = "0.1.0"\ndependencies = [\n "blake3",\n "serde",\n]\n\n[[package]]\nname = "aquilum-core"\nversion = "0.3.10"\ndependencies = [\n "akula-node-catalog",\n "blake3",\n "serde",\n]\n\n[[package]]\nname = "serde"\nversion = "1.0.0"\nsource = "registry+https://github.com/rust-lang/crates.io-index"\nchecksum = "example"\n';
const base={paths:[CORE,LOCK,'aquilum-app/core/src/node_catalog_lab.rs'],coreDiff:cargoDiff,lockBefore:before,lockAfter:after};
const flags=payload=>assess({...base,...payload});
test('node-catalog opt-in crate does not fan out unrelated OS labs',()=>{
  assert.equal(cargoAdditive(cargoDiff).safe,true);
  assert.equal(lockAdditive(before,after,local),true);
  assert.equal(flags({}).shared_any_risky,false);
});
test('existing dependency and feature changes reactivate impacted lanes',()=>{
  assert.equal(flags({coreDiff:cargoDiff+'+ring = "0.18"\n'}).shared_core_cargo_risky,true);
  assert.equal(flags({lockAfter:after.replace('version = "1.0.0"','version = "1.0.1"')}).shared_lock_risky,true);
});
test('default feature activation and dependency removal fail closed',()=>{
  assert.equal(cargoAdditive('+default = ["node-catalog-lab"]\n-default = []\n').safe,false);
  assert.equal(cargoAdditive('-node-catalog-lab = []\n').safe,false);
});
test('unrelated lock checksum cannot bypass all required OS checks',()=>{
  const x=after.replace('checksum = "example"','checksum = "different"');
  assert.equal(lockAdditive(before,x,local),false);
  assert.equal(flags({lockAfter:x}).shared_lock_risky,true);
});
test('fake local package name, version, or remote source fail closed',()=>{
  assert.equal(lockAdditive(before,after.replace('name = "akula-node-catalog"','name = "surprise"'),local),false);
  assert.equal(lockAdditive(before,after.replace('version = "0.1.0"','version = "9.9.9"'),local),false);
  assert.equal(lockAdditive(before,after.replace('name = "akula-node-catalog"\nversion = "0.1.0"','name = "akula-node-catalog"\nversion = "0.1.0"\nsource = "registry+bad"'),local),false);
});
test('owned source changes rely on own specialized workflow, not all manifest labs',()=>{
  assert.equal(flags({paths:['aquilum-app/core/src/server_installer_fixed_node_lab.rs']}).shared_any_risky,false);
  assert.equal(flags({paths:[CORE,LOCK,'aquilum-app/core/src/server_installer_fixed_node_lab.rs']}).shared_any_risky,false);
});
test('non-additive lib edits risky; additive gated module isolated',()=>{
  assert.equal(flags({paths:[LIB],libDiff:'-pub mod sync;\n'}).shared_core_lib_risky,true);
  const c='+example-probe = []\n',l='+#[cfg(feature = "example-probe")]\n+pub mod example_probe;\n';
  assert.equal(libAdditive(l,cargoAdditive(c).features),true);
  assert.equal(assess({paths:[CORE,LIB],coreDiff:c,libDiff:l}).shared_any_risky,false);
  assert.equal(libAdditive('+pub mod unlocked;\n',cargoAdditive(c).features),false);
});
test('root manifest and direct lock edits always retain previously owned gates',()=>{
  assert.equal(flags({paths:[ROOT]}).shared_root_cargo_risky,true);
  assert.equal(flags({paths:[LOCK]}).shared_lock_risky,true);
});

test('installed-owner OS security is required only for its owned files or a risky Core manifest',()=>{
  const owned=["aquilum-app/core/src/sync/host_install_unix_root.rs","aquilum-app/core/src/sync/host_install_witness.rs","aquilum-app/core/src/sync/mod.rs","aquilum-app/native/Cargo.toml",".github/workflows/sync-installed-os-owner-witness.yml","docs/sync/adr-0038-unix-root-owned-install-receipt.md"];
  for(const file of owned){
    const result=assess({paths:[file]});
    assert.equal(result.installed_owner_owned,true,file);
    assert.equal(result.shared_any_risky,false,file);
  }
  assert.equal(assess({paths:['README.md','aquilum-app/core/src/notion_api_probe.rs']}).installed_owner_owned,false);
  assert.equal(flags({}).installed_owner_owned,false,'optional Core crate does not start OS owner test');
  assert.equal(assess({paths:[CORE],coreDiff:'+ring = "0.18"\n'}).shared_core_cargo_risky,true,'risky Core still routes OS owner');
});


test('pure four-file Windows version bump avoids unrelated shared OS labs only',()=>{
  const coreBefore='[package]\nname = "aquilum-core"\nversion = "0.3.10"\n[dependencies]\nserde = "1"\n';
  const nativeBefore='[package]\nname = "aquilum-native"\nversion = "0.3.10"\n[features]\ndefault = []\n';
  const lockBefore='# generated\nversion = 4\n\n[[package]]\nname = "aquilum-core"\nversion = "0.3.10"\ndependencies = ["serde"]\n\n[[package]]\nname = "aquilum-native"\nversion = "0.3.10"\ndependencies = ["aquilum-core"]\n\n[[package]]\nname = "serde"\nversion = "1.0.0"\nchecksum = "unchanged"\n';
  const windowsBefore='{"productName": "Akula", "version": "0.3.10"}';
  const bump=s=>s.replaceAll('0.3.10','0.3.11');
  const paths=[CORE,LOCK,NATIVE,WINDOWS];
  const base={
    paths,coreBefore,coreAfter:bump(coreBefore),
    nativeBefore,nativeAfter:bump(nativeBefore),
    lockBefore,lockAfter:bump(lockBefore),
    windowsBefore,windowsAfter:bump(windowsBefore),
  };
  assert.equal(versionBumpOnly(base),true);
  const owned=assess({paths,coreDiff:'-version = "0.3.10"\n+version = "0.3.11"',
    lockBefore,lockAfter:bump(lockBefore),versionOnly:true});
  assert.equal(owned.shared_any_risky,false);
  assert.equal(owned.installed_owner_owned,false);
  // Cargo/lock edits still get full Rust workspace, RustSec and updater checks.
  // Only the separately routed OS/security laboratories are omitted.
  assert.equal(require('./ci-rust-scope.cjs').classify(paths),'workspace');
  const unsafe=[
    {lockAfter:bump(lockBefore).replace('checksum = "unchanged"','checksum = "changed"')},
    {lockAfter:bump(lockBefore)+'\n[[package]]\nname = "intruder"\nversion = "1.0.0"\n'},
    {coreAfter:bump(coreBefore).replace('serde = "1"','serde = "2"')},
    {nativeAfter:bump(nativeBefore).replace('default = []','default = ["unsafe"]')},
    {windowsAfter:bump(windowsBefore).replace('Akula','Aquilum')},
    {windowsAfter:bump(windowsBefore).replace('0.3.11','0.3.12')},
    {nativeAfter:nativeBefore},
    {coreBefore:bump(coreBefore),coreAfter:coreBefore},
    {paths:[...paths,'.github/workflows/app-checks.yml']},
    {paths:paths.slice(0,3)},
    {paths:[CORE,LOCK,NATIVE,ROOT]},
    {lockAfter:bump(lockBefore)+bump(lockBefore)},
  ];
  for(const variant of unsafe)assert.equal(versionBumpOnly({...base,...variant}),false,
    'unsafe metadata/feature/dependency/release-policy change must not skip OS labs');
  assert.equal(assess({paths:[CORE,LOCK,NATIVE,ROOT],versionOnly:true,
    coreDiff:'-version = "0.3.10"\n+version = "0.3.11"',lockBefore,lockAfter:bump(lockBefore)}).shared_any_risky,true);
});


test('Native package metadata is routed without duplicate direct OS workflows',()=>{
  const pure=[CORE,LOCK,NATIVE,WINDOWS];
  const direct=assess({paths:[NATIVE]});
  assert.equal(direct.native_manifest_risky,true);
  assert.equal(direct.installed_owner_owned,true);
  const metadata=assess({paths:pure,versionOnly:true,
    coreDiff:'-version = "0.3.10"\n+version = "0.3.11"',
    lockBefore:before,lockAfter:after});
  assert.equal(metadata.native_manifest_risky,false);
  assert.equal(metadata.installed_owner_owned,false);
  assert.equal(metadata.shared_any_risky,false);
  const mixed=assess({paths:[...pure,'.github/workflows/app-checks.yml'],versionOnly:true,
    coreDiff:'-version = "0.3.10"\n+version = "0.3.11"',
    lockBefore:before,lockAfter:after});
  assert.equal(mixed.native_manifest_risky,true);
  assert.equal(mixed.installed_owner_owned,true);
  assert.equal(mixed.shared_any_risky,true);
  for(const p of [NATIVE,'aquilum-app/native/src/workspace.rs']){
    const found=assess({paths:[p]});
    assert.equal(found.native_manifest_risky,p===NATIVE);
  }
});

const owned=require('./ci-shared-manifest-route.cjs');
test('owned tests run once via gate on source-only and mixed manifest diffs',()=>{for(const [k,items] of Object.entries(owned.OWNED_SUITES)){for(const p of items){assert.equal(owned.ownedRoutes([p])[k],true);assert.equal(owned.ownedRoutes([p,LOCK,NATIVE])[k],true);}assert.equal(owned.ownedRoutes(['README.md'])[k],false);}const p=owned.assess({paths:[LOCK,NATIVE,'aquilum-app/core/src/sync/mod.rs']});for(const k of Object.keys(owned.OWNED_SUITES))assert.equal(p[k],['owned_b0c_ssh','owned_b1c1_vm'].includes(k)?false:true);});

test('B0c Windows owner route is fail-closed for source-only and mixed Cargo without broad version-only routing',()=>{
  const owners=owned.OWNED_SUITES.owned_b0c_ssh;
  assert.equal(owners.length,14);
  assert.ok(owners.includes('.github/workflows/core-server-bootstrap-b0c-windows-ssh.yml'));
  assert.ok(owners.includes('aquilum-app/core/src/server_bootstrap_ssh_windows_lab.rs'));
  assert.equal(owned.assess({paths:[NATIVE]}).owned_b0c_ssh,false,
    'Native Cargo alone uses the existing native risk flag; not a second B0c route');
  assert.equal(owned.assess({paths:[NATIVE]}).native_manifest_risky,true);
  for(const file of owners){
    const single=owned.assess({paths:[file]});
    assert.equal(single.owned_b0c_ssh,true,'source-only route '+file);
    const mixed=owned.assess({paths:[file,NATIVE]});
    assert.equal(mixed.owned_b0c_ssh,true,'mixed route '+file);
    assert.equal(mixed.native_manifest_risky,true,'mixed native risk '+file);
  }
  assert.equal(owned.assess({paths:[CORE,LOCK,NATIVE,WINDOWS],versionOnly:true}).owned_b0c_ssh,false);
  assert.equal(owned.assess({paths:['README.md']}).owned_b0c_ssh,false);
});
